ost:"Total credits",downloadConfirmation:"Download confirmation",confirmDownloadSpend:"Confirm spending {credits} credits",paidDownloadWarning:"Paid qualities are submitted only after confirmation. If AFP accepts a purchase but does not return a delivery URL, the task is marked for review and is never purchased again automatically.",confirmDownload:"Confirm and download",previewDownload:"Review download",downloadSelectionTitle:"Download selected photos",downloadSelectionDescription:"Choose a quality and save location for each photo. The highest available free quality is selected by default.",downloadActionFailed:"Could not prepare the download. Refresh the options and try again.",downloadQuoteChanged:"The credit balance or quality quote changed. Review the updated total and confirm again.",downloadQueued:"The download is running in the background. Check Tasks for progress and results.",removeFavoritesTitle:"Remove from favorites",removeFavoritesWarning:"This only removes the selected photos from their source collections. It does not delete AFP photos. Each change is verified.",removeFromFavorites:"Remove selected photos",operationResult:"{count} completed",pending:"Pending review",copy:"Copy to collection",move:"Move to collection",moveSourceRequired:"These photos cannot be moved because their source collection is read-only or unknown.",targetCollection:"Target collection",chooseTarget:"Choose a target collection",collectionActionFailed:"The collection operation failed. Refresh the state and review the result.",transferSelectionTitle:"Transfer selected photos",confirmTransfer:"Confirm transfer",partial:"Partially complete",downloadTasks:"Download history",downloadTask:"Photo download",failedCount:"Failed",pendingCount:"Pending",purchasePending:"AFP accepted the purchase, but delivery is not confirmed. It will not be purchased again automatically. Check the account later.",hostStopped:"The task stopped when the Host exited.",downloadStatus_queued:"Queued",downloadSta